    const BAD_SCRUBBER_TEXT_RE = /\\b(volume|mute|brightness|subtitle|caption|quality|settings|speed|episode|playlist)\\b/i;

    function rectOf(el) {
        try {
            return el.getBoundingClientRect();
        } catch (_) {
            return {
                left: 0,
                top: 0,
                right: 0,
                bottom: 0,
                width: 0,
                height: 0
            };
        }
