    function centerOf(el) {
        const r = rectOf(el);

        return {
            x: r.left + r.width / 2,
            y: r.top + r.height / 2
        };
    }

    function areaOf(el) {
        const r = rectOf(el);
        return Math.max(0, r.width) * Math.max(0, r.height);
    }

    function markControllerActivity() {
