        if (isVcTimeRange(el)) return true;

        const text = getTextFor(el);

        if (BAD_SCRUBBER_TEXT_RE.test(text)) return false;

        const r = rectOf(el);

        return r.width >= 24 && r.height >= 4;
    }

    function isPlayerControl(el) {
        return !!el?.matches?.(PLAYER_CONTROL_SELECTORS);
    }

    function isContainerSelectable(el) {
        return isCard(el) || isRowLike(el) || isSourceOption(el) || isPlayerControl(el);
    }

    function getCardOwner(el) {
        return el?.closest?.(CARD_SELECTORS) || null;
    }

    function getRowOwner(el) {
        return el?.closest?.(ROW_SELECTORS) || null;
    }

    function getSourceOwner(el) {
        const source = el?.closest?.(SOURCE_OPTION_SELECTORS);

        if (source && SOURCE_TEXT_RE.test(getTextFor(source))) {
            return source;
        }

        return null;
    }

    function getPlayerOwner(el) {
        if (!el) return null;

        if (el.matches?.("video")) return el;

        const player = el.closest?.(PLAYER_CONTAINER_SELECTORS);

        if (player && isVisible(player)) return player;

        return null;
    }

    function getSelectableOwner(el) {
        return getCardOwner(el) || getRowOwner(el) || getSourceOwner(el) || getPlayerOwner(el);
    }

    function getTextFor(el) {
        if (!el) return "";

        const className =
            typeof el.className === "string"
                ? el.className
                : "";

        const parts = [
            el.innerText,
            el.textContent,
            el.value,
            el.getAttribute?.("aria-label"),
            el.getAttribute?.("title"),
            el.getAttribute?.("alt"),
            el.getAttribute?.("placeholder"),
            el.getAttribute?.("data-action"),
            el.getAttribute?.("data-testid"),
            el.getAttribute?.("data-value"),
            el.getAttribute?.("data-source"),
            el.getAttribute?.("data-provider"),
            el.getAttribute?.("data-server"),
            el.getAttribute?.("data-vc-element"),
            el.getAttribute?.("href"),
            className
        ];

        return parts
            .filter(Boolean)
            .join(" ")
            .replace(/\\s+/g, " ")
            .trim()
            .toLowerCase();
    }

    function isExternalLink(el) {
        if (!el || !el.matches?.('a[href]')) return false;

        const rawHref = el.getAttribute("href") || "";

        if (!rawHref || rawHref.startsWith("#") || rawHref.startsWith("/") || rawHref.startsWith("?")) {
            return false;
        }

        if (/^(magnet:|mailto:|tel:|irc:|ftp:)/i.test(rawHref)) {
            return true;
        }

        try {
            const url = new URL(rawHref, window.location.href);
            return url.origin !== window.location.origin;
        } catch (_) {
            return false;
        }
    }

    function wouldOpenBrowser(el) {
        if (!el) return false;

        if (isExternalLink(el)) return true;

        const link = el.closest?.('a[href]');

        if (link && isExternalLink(link)) return true;

        const text = getTextFor(el);

        return BAD_BROWSER_TEXT_RE.test(text);
    }

    function getZIndex(el) {
        const z = Number.parseInt(window.getComputedStyle(el).zIndex, 10);
        return Number.isFinite(z) ? z : 0;
    }

