            video.closest(PLAYER_CONTAINER_SELECTORS) ||
            video.closest('[class*="watch"], [class*="Watch"], [class*="episode"], [class*="Episode"]');

        if (root && isVisible(root) && areaOf(root) >= areaOf(video)) {
            return root;
