    function isImportantInnerControl(el, owner) {
        if (!el) return false;

        if (isTextInput(el)) return true;

        const isControl = el.matches(ACTIVATABLE_SELECTOR) || el.matches(PLAYER_CONTROL_SELECTORS);

        if (!isControl) return false;

        if (!owner) return true;

        const ownerArea = areaOf(owner);
        const controlArea = areaOf(el);

        if (ownerArea <= 0) return true;

        if (controlArea / ownerArea > 0.56) {
            return false;
        }

        return true;
    }

    function getOutermostSelectableContainers(root, selector) {
        const all = Array
            .from(root.querySelectorAll(selector))
            .filter((el) => isVisible(el) && !isDisabled(el));

        return all.filter((el) => {
            const parent = el.parentElement?.closest?.(selector);

            if (!parent) return true;
            if (!all.includes(parent)) return true;

            const parentArea = areaOf(parent);
            const ownArea = areaOf(el);

            return ownArea > parentArea * 0.92;
