    function getTextSourceOptions(root) {
        const candidates = Array
            .from(root.querySelectorAll(
                [
                    SOURCE_OPTION_SELECTORS,
                    'button',
                    'a[href]',
                    '[role="button"]',
                    '[role="option"]',
                    '[role="tab"]',
                    'div',
                    'span',
                    'p'
                ].join(",")
            ))
            .filter((el) => isVisible(el) && !isDisabled(el))
            .filter((el) => {
                const text = getTextFor(el);

                if (!SOURCE_TEXT_RE.test(text)) return false;

                const r = rectOf(el);

                if (r.width > window.innerWidth * 0.90 && r.height > window.innerHeight * 0.46) return false;
                if (r.width < 18 || r.height < 14) return false;

                const style = window.getComputedStyle(el);

                return (
                    style.cursor === "pointer" ||
                    el.matches(SOURCE_OPTION_SELECTORS) ||
                    el.matches(ACTIVATABLE_SELECTOR) ||
                    el.closest('[data-state], [role="radiogroup"], [role="tablist"], [role="listbox"], [class*="stream"], [class*="Stream"], [class*="source"], [class*="Source"], [class*="torrent"], [class*="Torrent"], [class*="provider"], [class*="Provider"]')
                );
            });

