    function wakePlayerControls(video) {
        if (!video) return;

        const root = getPlayerRoot(video);
        const targets = [root, video].filter(Boolean);

        for (const target of targets) {
            const r = rectOf(target);
            const x = r.left + r.width / 2;
            const y = r.top + r.height / 2;

            const base = {
                bubbles: true,
                cancelable: true,
                composed: true,
                clientX: x,
                clientY: y,
                screenX: x,
                screenY: y,
                pageX: x + window.scrollX,
                pageY: y + window.scrollY,
