        if (video && isVisible(video)) {
            controls.push(video);
        }

        if (!searchRoot) return controls;

        wakePlayerControls(video);

        const playerControls = Array
            .from(searchRoot.querySelectorAll(PLAYER_CONTROL_SELECTORS))
            .filter((el) => isVisible(el) && !isDisabled(el))
            .filter((el) => !wouldOpenBrowser(el));

        for (const control of playerControls) {
            if (!controls.includes(control)) {
                controls.push(control);
            }
        }

        return controls;
