    function scoreScrubberCandidate(el, video) {
        if (!el || !isVisible(el) || isDisabled(el)) return -Infinity;

        const text = getTextFor(el);
        const r = rectOf(el);

        if (BAD_SCRUBBER_TEXT_RE.test(text)) return -Infinity;
        if (r.width < 30 || r.height < 4) return -Infinity;

