        if (el.matches('[aria-label*="playback time" i]')) score += 3000;
        if (el.matches('input[type="range"]')) score += 800;
        if (el.matches('[role="slider"]')) score += 760;
        if (el.matches('[role="progressbar"]')) score += 600;
        if (el.matches('progress')) score += 540;

        if (/time-range|playback time|seek|scrub|timeline|progress|current-time|time/i.test(text)) score += 650;

        if (/volume|mute|brightness|speed|quality|subtitle|caption/i.test(text)) score -= 1200;

        if (r.width > 160) score += 240;
        if (r.width > 300) score += 180;
        if (r.height <= 40) score += 80;

        if (video) {
            const vr = rectOf(video);

            if (r.top > vr.top + vr.height * 0.45) score += 160;
            if (r.left >= vr.left - 80 && r.right <= vr.right + 80) score += 130;
        }

        return score;
