        const root = getPlayerRoot(video) || document;

        const roots = [
            root,
            document.fullscreenElement,
            document
        ].filter(Boolean);

        for (const searchRoot of roots) {
            try {
                const exact = searchRoot.querySelector('[data-vc-element="time-range"][role="slider"]');

