        const candidates = [];

        for (const searchRoot of roots) {
            try {
                for (const el of Array.from(searchRoot.querySelectorAll(PLAYER_SCRUBBER_SELECTORS))) {
                    if (!candidates.includes(el)) {
                        candidates.push(el);
                    }
