        const sources = getTextSourceOptions(root);
        const playerControls = getPlayerFocusables(root);

        const direct = Array
            .from(root.querySelectorAll(DIRECT_SELECTORS))
            .filter((el) => isVisible(el) && !isDisabled(el));

        const finalList = [];

        function add(el) {
            if (!el || finalList.includes(el)) return;
            if (!isVisible(el) || isDisabled(el)) return;
            if (shouldSkipHugeContainer(el)) return;

