            if (preferred) return preferred;

            const scopeCenter = centerOf(scope);

            return elements
                .slice()
                .sort((a, b) => {
                    const ac = centerOf(a);
                    const bc = centerOf(b);

                    const ad = Math.hypot(ac.x - scopeCenter.x, ac.y - scopeCenter.y);
                    const bd = Math.hypot(bc.x - scopeCenter.x, bc.y - scopeCenter.y);

