        let secondary = 0;
        let overlap = 0;
        let desiredPenalty = 0;

        if (direction === "right") {
            if (tr.left < cr.right - 6 && dx <= 14) return Infinity;

            primary = Math.max(0, tr.left - cr.right);
            secondary = absDy;
            overlap = overlapAmount(cr.top, cr.bottom, tr.top, tr.bottom);
            desiredPenalty = Math.abs(tc.y - (navMemory.desiredY || cc.y));
