        if (direction === "left") {
            if (tr.right > cr.left + 6 && dx >= -14) return Infinity;

            primary = Math.max(0, cr.left - tr.right);
            secondary = absDy;
            overlap = overlapAmount(cr.top, cr.bottom, tr.top, tr.bottom);
            desiredPenalty = Math.abs(tc.y - (navMemory.desiredY || cc.y));
