        if (direction === "down") {
            if (tr.top < cr.bottom - 6 && dy <= 14) return Infinity;

            primary = Math.max(0, tr.top - cr.bottom);
            secondary = absDx;
            overlap = overlapAmount(cr.left, cr.right, tr.left, tr.right);
            desiredPenalty = Math.abs(tc.x - (navMemory.desiredX || cc.x));
