        let score = 0;

        if (opensBrowser && !allowExternal) score -= 2000;

        if (el.matches('button, [role="button"], .UI-Button_root, .UI-IconButton_root')) score += 150;
        if (el.matches('[role="menuitem"], [role="option"], [data-radix-collection-item], [data-command-item], [cmdk-item]')) score += 120;
        if (el.matches('input, textarea, select, [contenteditable="true"]')) score += 90;
        if (el.matches('a[href], [role="link"]')) score += opensBrowser ? -350 : 80;

        if (/torrent|magnet|nyaa|anidex|seed|seeder|download|stream|debrid|online|local library/i.test(containerText)) score += 60;

        if (/local library/i.test(text)) score += 640;
        if (/torrent stream/i.test(text)) score += 640;
        if (/debrid stream/i.test(text)) score += 640;
        if (/online stream/i.test(text)) score += 640;

        if (/stream|watch|play now|play/i.test(text)) score += 540;
        if (/download|torrent|magnet/i.test(text)) score += 510;
        if (/select|choose|open|view|details/i.test(text)) score += 250;
        if (/confirm|continue|ok|yes|save|apply|submit/i.test(text)) score += 215;

        if (BAD_BROWSER_TEXT_RE.test(text) && !allowExternal) score -= 1000;
        if (/cancel|close|dismiss|delete|remove|clear|stop/i.test(text)) score -= 260;

        const containerArea = areaOf(container);
        const ownArea = areaOf(el);

        if (containerArea > 0) {
            const ratio = ownArea / containerArea;

            if (ratio > 0.22) score += 60;
            if (ratio > 0.55) score += opensBrowser && !allowExternal ? -300 : 80;
        }

        return score;
    }

    function findPrimaryAction(container, options) {
        if (!container) return null;

        const allowExternal = !!options?.allowExternal;
        const text = getTextFor(container);
        const isTorrentLike = /torrent|magnet|seed|seeder|debrid|stream|online|local library/i.test(text);

        if (!isContainerSelectable(container) && container.matches(ACTIVATABLE_SELECTOR)) {
            if (wouldOpenBrowser(container) && !allowExternal) return null;
            return container;
        }

        simulateHover(container);

        const controls = Array
            .from(container.querySelectorAll(ACTIVATABLE_SELECTOR))
            .filter((el) => isVisible(el) && !isDisabled(el));

        if (!controls.length) {
            return container;
        }

        const sorted = controls
            .map((el) => ({
                el,
                score: scoreActionCandidate(el, container, allowExternal)
            }))
            .sort((a, b) => b.score - a.score);

        if (sorted[0] && sorted[0].score > -500) {
            return sorted[0].el;
        }

        if (isTorrentLike && !allowExternal) {
            return container;
        }

        return controls.find((el) => !wouldOpenBrowser(el)) || container;
    }

    function getActivationTarget(focused, options) {
        if (!focused) return null;

        const allowExternal = !!options?.allowExternal;

        if (focused.matches?.("video")) {
            return focused;
        }

        if (isContainerSelectable(focused)) {
            return findPrimaryAction(focused, { allowExternal });
        }

        if (focused.matches(ACTIVATABLE_SELECTOR)) {
            if (wouldOpenBrowser(focused) && !allowExternal) return null;
            return focused;
        }

        const closest = focused.closest(ACTIVATABLE_SELECTOR);

        if (closest && !(wouldOpenBrowser(closest) && !allowExternal)) {
            return closest;
        }

        return focused;
    }

    function dispatchPointerMouseSequence(target) {
        const r = rectOf(target);

        const x = r.left + r.width / 2;
        const y = r.top + r.height / 2;

        const base = {
            bubbles: true,
            cancelable: true,
            composed: true,
            clientX: x,
            clientY: y,
            screenX: x,
            screenY: y,
            pageX: x + window.scrollX,
            pageY: y + window.scrollY,
            button: 0,
            buttons: 1
        };

        try {
            if (window.PointerEvent) {
                target.dispatchEvent(new PointerEvent("pointerover", Object.assign({}, base, { pointerType: "mouse", pointerId: 1 })));
                target.dispatchEvent(new PointerEvent("pointerenter", Object.assign({}, base, { pointerType: "mouse", pointerId: 1 })));
                target.dispatchEvent(new PointerEvent("pointermove", Object.assign({}, base, { pointerType: "mouse", pointerId: 1 })));
                target.dispatchEvent(new PointerEvent("pointerdown", Object.assign({}, base, { pointerType: "mouse", pointerId: 1 })));
            }

            target.dispatchEvent(new MouseEvent("mouseover", base));
            target.dispatchEvent(new MouseEvent("mouseenter", base));
            target.dispatchEvent(new MouseEvent("mousemove", base));
            target.dispatchEvent(new MouseEvent("mousedown", base));

            if (window.PointerEvent) {
                target.dispatchEvent(new PointerEvent("pointerup", Object.assign({}, base, { pointerType: "mouse", pointerId: 1, buttons: 0 })));
            }

            target.dispatchEvent(new MouseEvent("mouseup", Object.assign({}, base, { buttons: 0 })));
        } catch (_) {}
    }

    function makeKeyEvent(type, key) {
        const code =
            key === " "
                ? "Space"
                : key;

        const keyCodeMap = {
            " ": 32,
            Space: 32,
            Enter: 13,
            Escape: 27,
            Backspace: 8,
            ArrowLeft: 37,
            ArrowUp: 38,
            ArrowRight: 39,
            ArrowDown: 40,
            PageUp: 33,
            PageDown: 34,
            m: 77,
            f: 70,
            k: 75,
            j: 74,
            l: 76
        };

        const keyCode = keyCodeMap[key] || keyCodeMap[code] || 0;

        const event = new KeyboardEvent(type, {
            key,
            code,
            bubbles: true,
            cancelable: true,
            composed: true
        });

        try {
            Object.defineProperty(event, "keyCode", { get: () => keyCode });
            Object.defineProperty(event, "which", { get: () => keyCode });
            Object.defineProperty(event, "charCode", { get: () => type === "keypress" ? keyCode : 0 });
        } catch (_) {}

        return event;
    }

    function dispatchKeyboardActivation(target, key) {
        try {
            target.dispatchEvent(makeKeyEvent("keydown", key));
            target.dispatchEvent(makeKeyEvent("keypress", key));
            target.dispatchEvent(makeKeyEvent("keyup", key));
        } catch (_) {}
    }

    function dispatchPlayerFriendlyKey(key) {
        const video = getActiveVideo();
        const root = getPlayerRoot(video);

        wakePlayerControls(video);

        const targets = [
            document.activeElement,
            video,
            root,
            document.body,
            document,
            window
        ].filter(Boolean);

        for (const target of targets) {
            try {
                target.dispatchEvent(makeKeyEvent("keydown", key));
                target.dispatchEvent(makeKeyEvent("keypress", key));
                target.dispatchEvent(makeKeyEvent("keyup", key));
            } catch (_) {}
        }
    }

    function rememberTextSelection(target) {
        if (!target) return;

        try {
            if (
                target instanceof HTMLInputElement ||
                target instanceof HTMLTextAreaElement
            ) {
                keyboardSelectionStart = target.selectionStart;
                keyboardSelectionEnd = target.selectionEnd;
            }
        } catch (_) {}
    }

    function updateKeyboardPreview() {
        const keyboard = getOpenKeyboard();

        if (!keyboard || !keyboardTarget) return;

        const preview = keyboard.querySelector(".controller-virtual-keyboard-preview");

        if (!preview) return;

        if (
            keyboardTarget instanceof HTMLInputElement ||
            keyboardTarget instanceof HTMLTextAreaElement
        ) {
            preview.textContent = keyboardTarget.value || keyboardTarget.placeholder || "Text input";
        } else {
            preview.textContent = keyboardTarget.textContent || "Text input";
        }
    }

    function setTextTargetValueLikeNative(target, value) {
        if (
            target instanceof HTMLInputElement ||
            target instanceof HTMLTextAreaElement
        ) {
            const prototype =
                target instanceof HTMLTextAreaElement
                    ? HTMLTextAreaElement.prototype
                    : HTMLInputElement.prototype;

            const descriptor = Object.getOwnPropertyDescriptor(prototype, "value");

            if (descriptor && descriptor.set) {
                descriptor.set.call(target, value);
            } else {
                target.value = value;
            }

            return;
        }

        if (target.isContentEditable) {
            target.textContent = value;
        }
    }

    function getTextTargetValue(target) {
        if (
            target instanceof HTMLInputElement ||
            target instanceof HTMLTextAreaElement
        ) {
            return target.value || "";
        }

        if (target.isContentEditable) {
            return target.textContent || "";
        }

        return "";
    }

    function fireTextTargetUpdate(target, data) {
        try {
            target.dispatchEvent(new InputEvent("input", {
                bubbles: true,
                cancelable: true,
                composed: true,
                inputType: "insertText",
                data: data || ""
            }));
        } catch (_) {
            target.dispatchEvent(new Event("input", {
                bubbles: true,
                cancelable: true
            }));
        }

        target.dispatchEvent(new Event("change", {
            bubbles: true,
            cancelable: true
        }));
    }

    function insertIntoTextTarget(text) {
        const target = keyboardTarget;

        if (!target || !target.isConnected) return;

        const currentFocus = document.querySelector(".controller-focused");

        try {
            target.focus({ preventScroll: true });
        } catch (_) {}

        if (
            target instanceof HTMLInputElement ||
            target instanceof HTMLTextAreaElement
        ) {
            const value = target.value || "";
            const start =
                Number.isFinite(keyboardSelectionStart)
                    ? keyboardSelectionStart
                    : value.length;

            const end =
                Number.isFinite(keyboardSelectionEnd)
                    ? keyboardSelectionEnd
                    : start;

            const nextValue =
                value.slice(0, start) +
                text +
                value.slice(end);

            const nextPosition = start + text.length;

            setTextTargetValueLikeNative(target, nextValue);

            try {
                target.setSelectionRange(nextPosition, nextPosition);
            } catch (_) {}

            keyboardSelectionStart = nextPosition;
            keyboardSelectionEnd = nextPosition;

            fireTextTargetUpdate(target, text);
        } else if (target.isContentEditable) {
            try {
                document.execCommand("insertText", false, text);
            } catch (_) {
                target.textContent = (target.textContent || "") + text;
            }

            fireTextTargetUpdate(target, text);
        }

        updateKeyboardPreview();

        if (currentFocus && currentFocus.isConnected && currentFocus.closest('[data-controller-keyboard]')) {
            setFocus(currentFocus);
        }
    }

    function backspaceTextTarget() {
        const target = keyboardTarget;

        if (!target || !target.isConnected) return;

        const currentFocus = document.querySelector(".controller-focused");

        try {
            target.focus({ preventScroll: true });
        } catch (_) {}

        if (
            target instanceof HTMLInputElement ||
            target instanceof HTMLTextAreaElement
        ) {
            const value = target.value || "";
            const start =
                Number.isFinite(keyboardSelectionStart)
                    ? keyboardSelectionStart
                    : value.length;

            const end =
                Number.isFinite(keyboardSelectionEnd)
                    ? keyboardSelectionEnd
                    : start;

            let nextStart = start;
            let nextValue = value;

            if (start !== end) {
                nextValue = value.slice(0, start) + value.slice(end);
                nextStart = start;
            } else if (start > 0) {
                nextValue = value.slice(0, start - 1) + value.slice(end);
                nextStart = start - 1;
            }

            setTextTargetValueLikeNative(target, nextValue);

            try {
                target.setSelectionRange(nextStart, nextStart);
            } catch (_) {}

            keyboardSelectionStart = nextStart;
            keyboardSelectionEnd = nextStart;

            fireTextTargetUpdate(target, "");
        } else if (target.isContentEditable) {
            target.textContent = (target.textContent || "").slice(0, -1);

            fireTextTargetUpdate(target, "");
        }

        updateKeyboardPreview();

        if (currentFocus && currentFocus.isConnected && currentFocus.closest('[data-controller-keyboard]')) {
            setFocus(currentFocus);
        }
    }

    function clearTextTarget() {
        const target = keyboardTarget;

        if (!target || !target.isConnected) return;

        if (
            target instanceof HTMLInputElement ||
            target instanceof HTMLTextAreaElement
        ) {
            setTextTargetValueLikeNative(target, "");
            keyboardSelectionStart = 0;
            keyboardSelectionEnd = 0;

            try {
                target.setSelectionRange(0, 0);
            } catch (_) {}

            fireTextTargetUpdate(target, "");
        } else if (target.isContentEditable) {
            target.textContent = "";

            fireTextTargetUpdate(target, "");
        }

        updateKeyboardPreview();
    }

    function forceSearchNudgeSpace(target) {
        if (!target || !target.isConnected) {
            return function noop() {};
        }

        const originalValue = getTextTargetValue(target);

        let originalStart = null;
        let originalEnd = null;

        try {
            if (
                target instanceof HTMLInputElement ||
                target instanceof HTMLTextAreaElement
            ) {
                originalStart = target.selectionStart;
                originalEnd = target.selectionEnd;
            }
        } catch (_) {}

        try {
            target.focus({ preventScroll: true });
        } catch (_) {}

        const nudgedValue = originalValue + " ";

        setTextTargetValueLikeNative(target, nudgedValue);

        try {
            if (
                target instanceof HTMLInputElement ||
                target instanceof HTMLTextAreaElement
            ) {
                const position = nudgedValue.length;
                target.setSelectionRange(position, position);
                keyboardSelectionStart = position;
                keyboardSelectionEnd = position;
            }
        } catch (_) {}

        fireTextTargetUpdate(target, " ");
        updateKeyboardPreview();

        return function restoreOriginalSearchText() {
            if (!target || !target.isConnected) return;

            try {
                target.focus({ preventScroll: true });
            } catch (_) {}

            setTextTargetValueLikeNative(target, originalValue);

            try {
                if (
                    target instanceof HTMLInputElement ||
                    target instanceof HTMLTextAreaElement
                ) {
                    const restoreStart =
                        Number.isFinite(originalStart)
                            ? originalStart
                            : originalValue.length;

                    const restoreEnd =
                        Number.isFinite(originalEnd)
                            ? originalEnd
                            : restoreStart;

                    target.setSelectionRange(restoreStart, restoreEnd);
                    keyboardSelectionStart = restoreStart;
                    keyboardSelectionEnd = restoreEnd;
                }
            } catch (_) {}

            fireTextTargetUpdate(target, "");
            updateKeyboardPreview();
        };
    }

    function findSearchSubmitButton(target) {
        if (!target) return null;

        const roots = [
            target.closest("form"),
            target.closest('[role="search"]'),
            target.closest('[cmdk-root]'),
            target.closest('[data-command-root]'),
            target.closest('[class*="search"], [class*="Search"]'),
            target.closest('[data-radix-dialog-content]'),
            target.closest('[role="dialog"]'),
            target.parentElement,
            document
        ].filter(Boolean);

        const candidates = [];

        for (const root of roots) {
            try {
                const buttons = Array.from(root.querySelectorAll([
                    'button',
                    'button[type="submit"]',
                    '[role="button"]',
                    '.UI-Button_root',
                    '.UI-IconButton_root',
                    '[aria-label]',
                    '[title]',
                    '[data-testid]',
                    '[data-action]'
                ].join(",")));

                for (const button of buttons) {
                    if (!candidates.includes(button)) {
                        candidates.push(button);
                    }
                }
            } catch (_) {}
        }

        const scored = candidates
            .filter((el) => isVisible(el) && !isDisabled(el))
            .map((el) => {
                const text = getTextFor(el);

                let score = 0;

                if (el.matches('button[type="submit"]')) score += 500;
                if (/search|submit|go|apply|filter|magnif|lookup|find/i.test(text)) score += 450;
                if (/clear|reset|close|cancel|dismiss|back|x/i.test(text)) score -= 800;

                const r = rectOf(el);
                const tr = rectOf(target);

                if (Math.abs((r.top + r.bottom) / 2 - (tr.top + tr.bottom) / 2) < 80) {
                    score += 80;
                }

                if (r.left > tr.left) {
                    score += 40;
                }

                return { el, score };
            })
            .filter((item) => item.score > 0)
            .sort((a, b) => b.score - a.score);

        return scored[0]?.el || null;
    }

    function dispatchEnterThroughSearch(target) {
        if (!target) return;

        const form = target.closest?.("form");

        const roots = [
            target,
            form,
            target.closest('[role="search"]'),
            target.closest('[cmdk-root]'),
            target.closest('[data-command-root]'),
            target.closest('[class*="search"], [class*="Search"]'),
            target.closest('[data-radix-dialog-content]'),
            target.closest('[role="dialog"]'),
            document.body,
            document,
            window
        ].filter(Boolean);

        for (const root of roots) {
            try {
                root.dispatchEvent(makeKeyEvent("keydown", "Enter"));
                root.dispatchEvent(makeKeyEvent("keypress", "Enter"));
                root.dispatchEvent(makeKeyEvent("keyup", "Enter"));
            } catch (_) {}
        }
    }

    function submitTextTarget() {
        const target = keyboardTarget;

        if (!target || !target.isConnected) return;

        try {
            target.focus({ preventScroll: true });
        } catch (_) {}

        const restoreNudge = forceSearchNudgeSpace(target);

        setTimeout(() => {
            try {
                target.dispatchEvent(new Event("input", {
                    bubbles: true,
                    cancelable: true
                }));

                target.dispatchEvent(new Event("change", {
                    bubbles: true,
                    cancelable: true
                }));
            } catch (_) {}

            dispatchEnterThroughSearch(target);

            const form = target.closest?.("form");

            if (form) {
                try {
                    form.dispatchEvent(new SubmitEvent("submit", {
                        bubbles: true,
                        cancelable: true,
                        submitter: findSearchSubmitButton(target)
                    }));
                } catch (_) {
                    try {
                        form.dispatchEvent(new Event("submit", {
                            bubbles: true,
                            cancelable: true
                        }));
                    } catch (_) {}
                }

                try {
                    form.requestSubmit?.();
                } catch (_) {}
            }

            const searchButton = findSearchSubmitButton(target);

            if (searchButton) {
                setTimeout(() => {
                    activateTarget(searchButton, { allowExternal: false });
                }, 35);
            }

            setTimeout(() => {
                restoreNudge();
            }, 180);

        }, 35);
    }

    function hideVirtualKeyboard() {
        const keyboard = getOpenKeyboard();

        if (keyboard) {
            try {
                keyboard.remove();
            } catch (_) {}
        }

        const target = keyboardTarget;

        keyboardTarget = null;
        keyboardShift = false;
        keyboardSelectionStart = null;
        keyboardSelectionEnd = null;

        if (target && target.isConnected) {
            try {
                target.focus({ preventScroll: true });
            } catch (_) {}
        }

        setTimeout(scheduleFocusRefresh, 50);
    }

    function handleVirtualKey(key) {
        if (!keyboardTarget || !keyboardTarget.isConnected) {
            hideVirtualKeyboard();
            return;
        }

        if (key === "shift") {
            keyboardShift = !keyboardShift;
            renderKeyboardKeys();
            setTimeout(scheduleFocusRefresh, 20);
            return;
        }

        if (key === "backspace") {
            backspaceTextTarget();
            return;
        }

        if (key === "space") {
            insertIntoTextTarget(" ");
            return;
        }

        if (key === "clear") {
            clearTextTarget();
            return;
        }

        if (key === "enter") {
            submitTextTarget();
            return;
        }

        if (key === "done") {
            submitTextTarget();
            setTimeout(() => {
                hideVirtualKeyboard();
            }, 300);
            return;
        }

        insertIntoTextTarget(keyboardShift ? key.toUpperCase() : key);
    }

    function createKeyButton(key, label, extraClass) {
        const button = document.createElement("button");

        button.type = "button";
        button.className = "controller-key" + (extraClass ? " " + extraClass : "");
        button.setAttribute("data-controller-key", key);
        button.textContent = label;

        button.addEventListener("click", () => {
            markControllerActivity();
            handleVirtualKey(key);
        });

        return button;
    }

    function renderKeyboardKeys() {
        const keyboard = getOpenKeyboard();

        if (!keyboard) return;

        const body = keyboard.querySelector(".controller-virtual-keyboard-body");

        if (!body) return;

        body.innerHTML = "";

        const rows = [
            ["1","2","3","4","5","6","7","8","9","0"],
            ["q","w","e","r","t","y","u","i","o","p"],
            ["a","s","d","f","g","h","j","k","l"],
            ["shift","z","x","c","v","b","n","m","backspace"],
            ["space","clear","enter","done"]
        ];

        for (const row of rows) {
            const rowEl = document.createElement("div");
            rowEl.className = "controller-virtual-keyboard-row";

            for (const key of row) {
                let label = key;
                let extraClass = "";

                if (key === "shift") {
                    label = keyboardShift ? "Shift On" : "Shift";
                    extraClass = "controller-key-wide";
                } else if (key === "backspace") {
                    label = "⌫";
                    extraClass = "controller-key-wide";
                } else if (key === "space") {
                    label = "Space";
                    extraClass = "controller-key-space";
                } else if (key === "clear") {
                    label = "Clear";
                    extraClass = "controller-key-wide";
                } else if (key === "enter") {
                    label = "Enter";
                    extraClass = "controller-key-wide";
                } else if (key === "done") {
                    label = "Done";
                    extraClass = "controller-key-wide";
                } else if (keyboardShift && /^[a-z]$/.test(key)) {
                    label = key.toUpperCase();
                }

                rowEl.appendChild(createKeyButton(key, label, extraClass));
            }

            body.appendChild(rowEl);
        }
    }

    function showVirtualKeyboard(target) {
        if (!target || !isTextInput(target)) return;

        keyboardTarget = target;
        keyboardShift = false;

        rememberTextSelection(target);

        let keyboard = getOpenKeyboard();

        if (!keyboard) {
            keyboard = document.createElement("div");
            keyboard.className = "controller-virtual-keyboard";
            keyboard.setAttribute("data-controller-keyboard", "true");
            keyboard.setAttribute("role", "dialog");
            keyboard.setAttribute("aria-label", "Controller keyboard");

            const header = document.createElement("div");
            header.className = "controller-virtual-keyboard-header";

            const title = document.createElement("div");
            title.textContent = "Controller Keyboard";

            const preview = document.createElement("div");
            preview.className = "controller-virtual-keyboard-preview";

            header.appendChild(title);
            header.appendChild(preview);

            const body = document.createElement("div");
            body.className = "controller-virtual-keyboard-body";

            keyboard.appendChild(header);
            keyboard.appendChild(body);

            document.body.appendChild(keyboard);
        }

        updateKeyboardPreview();
        renderKeyboardKeys();

        setTimeout(() => {
            const firstKey = keyboard.querySelector('[data-controller-key]');

            if (firstKey) {
                setFocus(firstKey);
            }
        }, 40);
    }

    function activateTarget(target, options) {
        if (!target) return false;

        const allowExternal = !!options?.allowExternal;

        if (target.matches?.('[data-controller-key]')) {
            handleVirtualKey(target.getAttribute("data-controller-key"));
            return true;
        }

        if (isTextInput(target)) {
            try {
                target.focus({ preventScroll: true });
            } catch (_) {}

            rememberTextSelection(target);
            showVirtualKeyboard(target);
            return true;
        }

        if (target.matches?.("video")) {
            wakePlayerControls(target);
            dispatchPlayerFriendlyKey(" ");
            return true;
        }

        if (target.matches?.(PLAYER_SCRUBBER_SELECTORS) && getActiveVideo()) {
            seekPlayerFriendly(PLAYER_SEEK_SECONDS);
            return true;
        }

        if (wouldOpenBrowser(target) && !allowExternal) {
            dispatchKeyboardActivation(target, "Enter");
            return false;
        }

        try {
            target.focus({ preventScroll: true });
        } catch (_) {}

        try {
            target.classList.add("controller-pressed");
            setTimeout(() => {
                try {
                    target.classList.remove("controller-pressed");
                } catch (_) {}
            }, 120);
        } catch (_) {}

        dispatchPointerMouseSequence(target);

        try {
            target.click();
        } catch (_) {}

        const role = target.getAttribute("role");

        if (
            role === "menuitem" ||
            role === "option" ||
            role === "tab" ||
            role === "checkbox" ||
            role === "switch" ||
            role === "radio" ||
            role === "combobox" ||
            target.matches('[data-radix-collection-item], [data-command-item], [cmdk-item]')
        ) {
            dispatchKeyboardActivation(target, "Enter");
            dispatchKeyboardActivation(target, " ");
        } else if (!target.matches('button, a[href], input, textarea, select, summary, label[for]')) {
            dispatchKeyboardActivation(target, "Enter");
        }

        return true;
    }

    function clickFocused() {
        const focused = document.querySelector(".controller-focused");

        if (!focused) {
            if (isPlayerPage()) {
                dispatchPlayerFriendlyKey(" ");
            }

            return;
        }

        const allowExternal =
            focused.matches?.('a[href]') &&
            wouldOpenBrowser(focused);

        const target = getActivationTarget(focused, { allowExternal });

        if (!target) {
            dispatchKeyboardActivation(focused, "Enter");
            setTimeout(ensureFocus, 245);
            return;
        }

        activateTarget(target, { allowExternal });

        setTimeout(ensureFocus, 245);
    }

    function dispatchEscape(target) {
        if (!target) return;

        try {
            target.dispatchEvent(makeKeyEvent("keydown", "Escape"));
            target.dispatchEvent(makeKeyEvent("keyup", "Escape"));
        } catch (_) {}
    }

    function findCloseButton(scope) {
        if (!scope || scope === document) return null;

        const candidates = Array
            .from(scope.querySelectorAll(
                [
                    '[data-radix-dialog-close]',
                    '[data-radix-alert-dialog-cancel]',
                    '[data-radix-popover-close]',
                    '[data-dismiss]',
                    '[aria-label]',
                    'button',
                    '[role="button"]',
                    '.UI-Button_root',
                    '.UI-IconButton_root'
                ].join(",")
            ))
            .filter((el) => isVisible(el) && !isDisabled(el));

        if (!candidates.length) return null;

        const scored = candidates
            .map((el) => {
                const text = getTextFor(el);

                let score = 0;

                if (/close|dismiss|cancel|back|esc|escape|x/i.test(text)) score += 500;
                if (el.hasAttribute("data-radix-dialog-close")) score += 450;
                if (el.hasAttribute("data-radix-alert-dialog-cancel")) score += 430;
                if (el.hasAttribute("data-radix-popover-close")) score += 420;
                if (/confirm|delete|remove|submit|save|download|stream|play/i.test(text)) score -= 500;

                const r = rectOf(el);
                const sr = rectOf(scope);

                if (r.top < sr.top + 90 && r.right > sr.right - 120) score += 120;

                return { el, score };
            })
            .sort((a, b) => b.score - a.score);

        return scored[0]?.score > 0 ? scored[0].el : null;
    }

    function closeOpenOverlay() {
        if (isKeyboardOpen()) {
            hideVirtualKeyboard();
            return true;
        }

        const scope = getActiveScope();

        if (scope === document || scope === document.fullscreenElement) return false;

        dispatchEscape(document.activeElement);
        dispatchEscape(scope);
        dispatchEscape(document);
        dispatchEscape(window);

        setTimeout(() => {
            if (!scope.isConnected || !isVisible(scope)) {
                scheduleFocusRefresh();
                return;
            }

            const closeButton = findCloseButton(scope);

            if (closeButton) {
                activateTarget(closeButton, { allowExternal: false });
                setTimeout(scheduleFocusRefresh, 120);
            }
        }, 70);

        return true;
    }

    function goBackOrCloseModal() {
        if (closeOpenOverlay()) return;

        if (document.fullscreenElement) {
            dispatchEscape(document.fullscreenElement);
            return;
        }

        window.history.back();
        setTimeout(ensureFocus, 420);
    }

    function pickActiveDirection(lx, ly, dRight, dLeft, dDown, dUp) {
        if (dRight) return "right";
        if (dLeft) return "left";
        if (dDown) return "down";
        if (dUp) return "up";

        const absX = Math.abs(lx);
        const absY = Math.abs(ly);

        if (absX < STICK_TRIGGER && absY < STICK_TRIGGER) return null;

        if (absX >= absY) {
            return lx > 0 ? "right" : "left";
        }

        return ly > 0 ? "down" : "up";
    }

    function findReaderPageButton(direction) {
        const candidates = Array
            .from(document.querySelectorAll(
                [
                    'button',
                    '[role="button"]',
                    'a[href]',
                    '.UI-Button_root',
                    '.UI-IconButton_root',
                    '[aria-label]',
                    '[title]',
                    '[data-action]'
                ].join(",")
            ))
            .filter((el) => isVisible(el) && !isDisabled(el))
            .filter((el) => !wouldOpenBrowser(el));

        const scored = candidates
            .map((el) => {
                const text = getTextFor(el);

                let score = 0;

                if (direction === "right") {
                    if (/next|forward|right|page down|chapter next/i.test(text)) score += 500;
                    if (/previous|prev|back|left|page up/i.test(text)) score -= 500;
                } else {
                    if (/previous|prev|back|left|page up|chapter prev/i.test(text)) score += 500;
                    if (/next|forward|right|page down/i.test(text)) score -= 500;
                }

                const r = rectOf(el);

                if (direction === "right" && r.right > window.innerWidth * 0.62) score += 70;
                if (direction === "left" && r.left < window.innerWidth * 0.38) score += 70;

                return { el, score };
            })
            .filter((item) => item.score > 0)
            .sort((a, b) => b.score - a.score);

        return scored[0]?.el || null;
    }

    function dispatchReaderKey(direction) {
        const key = direction === "right" ? "ArrowRight" : "ArrowLeft";
        const altKey = direction === "right" ? "PageDown" : "PageUp";

        const targets = [
            document.activeElement,
            document.body,
            document,
            window
        ];

        for (const target of targets) {
            if (!target) continue;

            try {
                target.dispatchEvent(makeKeyEvent("keydown", key));
                target.dispatchEvent(makeKeyEvent("keyup", key));
                target.dispatchEvent(makeKeyEvent("keydown", altKey));
                target.dispatchEvent(makeKeyEvent("keyup", altKey));
            } catch (_) {}
        }
    }

    function turnReaderPage(direction) {
        const now = performance.now();

        if (now - lastReaderPageAt < READER_PAGE_COOLDOWN) return false;

        lastReaderPageAt = now;

        const button = findReaderPageButton(direction);

        if (button) {
            activateTarget(button, { allowExternal: false });
        } else {
            dispatchReaderKey(direction);
        }

        return true;
    }

    function handleRightStick(rx, ry) {
        const absX = Math.abs(rx);
        const absY = Math.abs(ry);

        if (isReaderActive() && absX > RIGHT_STICK_TRIGGER && absX > absY) {
            turnReaderPage(rx > 0 ? "right" : "left");
            return;
        }

        if (getActiveVideo()) {
            const video = getActiveVideo();

            if (video) {
                wakePlayerControls(video);
            }

            if (absX > RIGHT_STICK_TRIGGER && absX > absY) {
                seekPlayerFriendly(rx > 0 ? PLAYER_SEEK_SECONDS : -PLAYER_SEEK_SECONDS);
                return;
            }
        }

        if (rx || ry) {
            window.scrollBy({
                left: rx * SCROLL_SPEED,
                top: ry * SCROLL_SPEED,
                behavior: "auto"
            });
        }
    }

    function updateDirectionalHold(activeDir) {
        stopAllDirectionsExcept(activeDir);

        if (!activeDir) return;

        startHold(activeDir, () => spatialMove(activeDir));
    }

    function inputLoop() {
        const gamepads = navigator.getGamepads();

        for (let i = 0; i < gamepads.length; i++) {
            const gp = gamepads[i];

            if (!gp) continue;

            const lx = Math.abs(gp.axes[0]) > AXIS_DEAD_ZONE ? gp.axes[0] : 0;
            const ly = Math.abs(gp.axes[1]) > AXIS_DEAD_ZONE ? gp.axes[1] : 0;

            const rx = Math.abs(gp.axes[2]) > AXIS_DEAD_ZONE ? gp.axes[2] : 0;
            const ry = Math.abs(gp.axes[3]) > AXIS_DEAD_ZONE ? gp.axes[3] : 0;

            const dRight = gp.buttons[15]?.pressed;
            const dLeft = gp.buttons[14]?.pressed;
            const dDown = gp.buttons[13]?.pressed;
            const dUp = gp.buttons[12]?.pressed;

            const buttons = {
                a: gp.buttons[0]?.pressed,
                b: gp.buttons[1]?.pressed,
                x: gp.buttons[2]?.pressed,
                y: gp.buttons[3]?.pressed,
                lb: gp.buttons[4]?.pressed,
                rb: gp.buttons[5]?.pressed,
                start: gp.buttons[9]?.pressed
            };

            const hasControllerActivity =
                lx ||
                ly ||
                rx ||
                ry ||
                dRight ||
                dLeft ||
                dDown ||
                dUp ||
                Object.keys(buttons).some((key) => buttons[key] && !lastButtons[key]);

            if (hasControllerActivity) {
                markControllerActivity();
            }

            ensureFocus();

            const activeDirection = pickActiveDirection(
                lx,
                ly,
                dRight,
                dLeft,
                dDown,
                dUp
            );

            updateDirectionalHold(activeDirection);

            if (!activeDirection) {
                resetNavMemory();
            }

            handleRightStick(rx, ry);

            if (buttons.a && !lastButtons.a) {
                clickFocused();
            }

            if (buttons.b && !lastButtons.b) {
                goBackOrCloseModal();
            }

            if (getActiveVideo()) {
                const video = getActiveVideo();

                if (video) {
                    wakePlayerControls(video);
                }

                if (buttons.start && !lastButtons.start) {
                    dispatchPlayerFriendlyKey(" ");
                }

                if (buttons.x && !lastButtons.x) {
                    dispatchPlayerFriendlyKey("m");
                }

                if (buttons.y && !lastButtons.y) {
                    dispatchPlayerFriendlyKey("f");
                }

                if (buttons.lb && !lastButtons.lb) {
                    seekPlayerFriendly(-PLAYER_BIG_SEEK_SECONDS);
                }

                if (buttons.rb && !lastButtons.rb) {
                    seekPlayerFriendly(PLAYER_BIG_SEEK_SECONDS);
                }
            }

            lastButtons = buttons;

            break;
        }

        rafId = requestAnimationFrame(inputLoop);
    }

    function startInputLoop() {
        if (rafId) cancelAnimationFrame(rafId);

        ensureFocus();

        rafId = requestAnimationFrame(inputLoop);
    }

    function stopInputLoop() {
        if (rafId) cancelAnimationFrame(rafId);

        rafId = null;

        clearAllHolds();
        clearVisualFocus();
        clearHover();
        hideVirtualKeyboard();

        lastButtons = {};
        resetNavMemory();

        showMouseCursor();
    }

    const originalPushState = history.pushState.bind(history);
    const originalReplaceState = history.replaceState.bind(history);

    function onRouteChange() {
        clearVisualFocus();
        clearHover();
        hideVirtualKeyboard();
        resetNavMemory();

        setTimeout(ensureFocus, 420);
    }

    history.pushState = (...args) => {
        originalPushState(...args);
        onRouteChange();
    };

    history.replaceState = (...args) => {
        originalReplaceState(...args);
        onRouteChange();
    };

    window.addEventListener("popstate", onRouteChange);

    const mutationObserver = new MutationObserver(() => {
        scheduleFocusRefresh();
    });

    try {
        mutationObserver.observe(document.body, {
            childList: true,
            subtree: true,
            attributes: true,
            attributeFilter: [
                "data-state",
                "aria-hidden",
                "aria-expanded",
                "aria-disabled",
                "disabled",
                "class",
                "style"
            ]
        });
    } catch (_) {}

    window.addEventListener("gamepadconnected", (e) => {
        console.log("[Seanime] Controller connected:", e.gamepad.id);
        startInputLoop();
    });

    window.addEventListener("gamepaddisconnected", () => {
        const anyConnected = Array
            .from(navigator.getGamepads())
            .some((g) => g !== null);

        if (!anyConnected) stopInputLoop();
    });

    if (
        Array.from(navigator.getGamepads())
            .some((g) => g !== null)
    ) {
        startInputLoop();
    }

})();
        `;

        const injectController = async () => {
            try {
                const head = await ctx.dom.queryOne("head");

                if (!head) return;

                const script = await ctx.dom.createElement("script");

                script.setText(getControllerScript());

                head.append(script);

                setTimeout(async () => {
                    try {
                        script.remove();
                    } catch (_) {}
                }, 300);

            } catch (err) {
                console.error(
                    "[Seanime] Failed to inject controller runtime:",
                    err
                );
            }
        };

        injectController();

        const tray = ctx.newTray({
            tooltipText: "Controller Support Active",
            iconUrl: "https://raw.githubusercontent.com/Bas1874/Doom-Seanime/main/icons/Doom.png",
            withContent: false,
        });

        tray.onClick(() => {
            injectController();
        });
    });
